#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int mn(int a, int b) {
    return a < b ? a : b;
}
int mx(int a, int b) {
    return a > b ? a : b;
}
int read(void) {
    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a) {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x) {
    printf("%d ", x);
}
void emitstr(int* a, int n) {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void) {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int ans = 0, found = 0, i = 0, j = 0, l = 0, m = 0, n = 0, p = 0, q = 0, r = 0, x = 0, y = 0;
    // 输入数组各自有序；平台最终要求中位数的两倍。
    n = read();
    m = read();
    for (i = 0; i < n; i += 1) {
        a[i] = read();
    }
    for (i = 0; i < m; i += 1) {
        b[i] = read();
    }
    l = 0;
    r = n;
    found = 0;
    while ((l <= r) && (found == 0)) {
        i = ((l + r) / 2);
        // 固定左半总数量，a 取 i 个后 b 必须取 j 个。
        j = ((((n + m) + 1) / 2) - i);
        if (j < 0) {
            r = (i - 1);
        }
        else {
            if (j > m) {
                l = (i + 1);
            }
            else {
                // 缺失边界使用超出输入范围的哨兵，避免空数组或端点越界。
                x = (-1000000000);
                y = (-1000000000);
                p = 1000000000;
                q = 1000000000;
                if (i > 0) {
                    x = a[(i - 1)];
                }
                if (j > 0) {
                    y = b[(j - 1)];
                }
                if (i < n) {
                    p = a[i];
                }
                if (j < m) {
                    q = b[j];
                }
                // 交叉边界有序即得到正确分割，按奇偶输出中位数的两倍。
                if ((x <= q) && (y <= p)) {
                    ans = (mx(x, y) * 2);
                    if (((n + m) % 2) == 0) {
                        ans = (mx(x, y) + mn(p, q));
                    }
                    emit(ans);
                    found = 1;
                }
                else {
                    if (x > q) {
                        r = (i - 1);
                    }
                    else {
                        l = (i + 1);
                    }
                }
            }
        }
    }
    return 0;
}

